141	    }
142	
143	    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
144	    @Transient
145	    public String getMembershipNumber() {
146	        return MembershipNumber.of(this.customerCode, this.registrationDate);
147	    }
148	
