157	    }
158	
159	    public void setNamesakeCount(Integer namesakeCount) {
160	        this.namesakeCount = namesakeCount;
161	    }
162	
163	    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
164	     *  captured when the owner was created, including this owner. */
165	    public Integer getHouseholdMemberCount() {
166	        return this.householdMemberCount;
167	    }
168	
169	    public void setHouseholdMemberCount(Integer householdMemberCount) {
170	        this.householdMemberCount = householdMemberCount;
171	    }
172	
173	    /** True when this owner, at creation, shared an existing owner's last name and postcode
174	     *  but had a different telephone (a soft, non-hard duplicate). */
175	    public Boolean getPossibleDuplicate() {
176	        return this.possibleDuplicate;
177	    }
178	
179	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
180	        this.possibleDuplicate = possibleDuplicate;
181	    }
182	
183	    /** Id of the existing owner this owner possibly duplicates, when {@link #getPossibleDuplicate()}. */
184	    public Integer getPossibleDuplicateOf() {
185	        return this.possibleDuplicateOf;
186	    }
187	
188	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
189	        this.possibleDuplicateOf = possibleDuplicateOf;
190	    }
191	
192	    /** True when this owner's city already held between 40 and 49 owners (approaching the 50
193	     *  capacity limit) at the time it was created. */
194	    public Boolean getCapacityWarning() {
