203	     *  create endpoint's duplicate and identity checks. False for a newly created owner. */
204	    public boolean isDeleted() {
205	        return this.deleted;
206	    }
207	
208	    public void setDeleted(boolean deleted) {
209	        this.deleted = deleted;
210	    }
211	
212	    public String getEmail() {
213	        return this.email;
214	    }
215	
216	    public void setEmail(String email) {
217	        this.email = email == null ? null : email.toLowerCase();
218	    }
219	
220	    public String getAddress() {
221	        return this.address;
222	    }
223	
