249	    private String composeAddress() {
250	        if (this.addressLine1 == null || this.addressLine1.isBlank()) {
251	            return this.flatAddress;
252	        }
253	        return this.addressLine2 == null ? this.addressLine1 : this.addressLine1 + " " + this.addressLine2;
