274	    }
275	
276	    public void setTelephone(String telephone) {
277	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
278	    }
279	
280	    protected Set<Pet> getPetsInternal() {
281	        if (this.pets == null) {
282	            this.pets = new HashSet<>();
