18	/**
19	 * Computes an owner's {@code checkDigit}: the Luhn check digit (0-9) over the
20	 * digits contained in the {@code customerCode}, ignoring any non-digit characters.
21	 */
22	public final class CheckDigit {
23	
24	    private CheckDigit() {
25	    }
26	
27	    /**
