29	     * @return the Luhn check digit, or {@code null} if {@code customerCode} is null
30	     */
31	    public static Integer of(String customerCode) {
32	        if (customerCode == null) {
33	            return null;
34	        }
35	        int sum = 0;
36	        boolean dbl = true;
37	        for (int i = customerCode.length() - 1; i >= 0; i--) {
38	            char c = customerCode.charAt(i);
39	            if (c < '0' || c > '9') {
40	                continue;
41	            }
42	            int d = c - '0';
43	            if (dbl && (d *= 2) > 9) {
44	                d -= 9;
45	            }
46	            sum += d;
47	            dbl = !dbl;
48	        }
49	        return (10 - (sum % 10)) % 10;
50	    }
