20	/**
21	 * Fiscal-year arithmetic for a year that starts on 1 July. The fiscal year is named
22	 * for the calendar year it ends in, so July–December fall in the following year's
23	 * fiscal year and its {@code label} is {@code FY<YY>}, e.g. {@code FY26}.
24	 */
25	public final class FiscalYear {
26	
27	    private FiscalYear() {
28	    }
29	
30	    /** The fiscal year that contains {@code date}. */
31	    public static int of(LocalDate date) {
32	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
33	    }
34	
35	    /** {@code FY<YY>} for the fiscal year of the business-day-adjusted {@code date},
36	     *  or {@code null} when {@code date} is null. */
37	    public static String label(LocalDate date) {
38	        return date == null ? null : String.format("FY%02d", of(BusinessDay.adjust(date)) % 100);
39	    }
40	
41	    /** Whole fiscal years elapsed from {@code date} to {@code asOf}. */
42	    public static int elapsed(LocalDate date, LocalDate asOf) {
43	        return of(asOf) - of(date);
44	    }
45	}
