32	
33	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
34	
35	    /** Monotonically increasing sequence stamped on each structured create event. */
36	    private static final AtomicLong SEQ = new AtomicLong();
37	
38	    @PostPersist
39	    void onCreate(Owner owner) {
40	        int membershipLevel = MembershipLevel.of(MembershipLevel.points(owner.getNamesakeCount(),
41	            owner.getEmail(), owner.getHouseholdMemberCount(), owner.getRegistrationDate()));
42	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
43	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
44	            membershipLevel, owner.getMembershipNumber());
45	        AUDIT.info("{}", String.format(
46	            "{\"seq\":%d,\"ownerId\":%d,\"customerCode\":\"%s\",\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
47	            SEQ.incrementAndGet(), owner.getId(), owner.getCustomerCode(), membershipLevel));
48	    }
