16	package org.springframework.samples.petclinic.model;
17	
18	import java.time.LocalDate;
19	
20	/**
21	 * Derives an owner's membership standing assigned on creation. {@code points} start at
22	 * {@code 0} and add {@code 2} for a present email, {@code 1} for a {@code namesakeCount}
23	 * of {@code 0}, {@code 2} for a household of at least three members and {@code 3} once the
24	 * owner's tenure exceeds one elapsed fiscal year. Those points map to a {@code level} of
25	 * {@code 1} ({@code 0-1}), {@code 2} ({@code 2-3}), {@code 3} ({@code 4-5}) or {@code 4}
26	 * ({@code 6} or more).
27	 */
28	public final class MembershipLevel {
29	
30	    /** Elapsed fiscal years of tenure required before the tenure points are awarded. */
31	    private static final int TENURE_POINTS_YEARS = 1;
32	
33	    private MembershipLevel() {
34	    }
35	
36	    /**
37	     * @param namesakeCount        number of pre-existing namesakes when the owner was created
38	     * @param email                the owner's email, if any
39	     * @param householdMemberCount number of members in the owner's household
40	     * @param registrationDate     the date the owner was registered, used to derive tenure
41	     * @return the membership points, {@code 0} or more
42	     */
43	    public static int points(Integer namesakeCount, String email, Integer householdMemberCount,
44	            LocalDate registrationDate) {
45	        int points = 0;
46	        if (email != null && !email.isBlank()) {
47	            points += 2;
48	        }
49	        if (Integer.valueOf(0).equals(namesakeCount)) {
50	            points += 1;
51	        }
52	        if (householdMemberCount != null && householdMemberCount >= 3) {
53	            points += 2;
54	        }
55	        if (exceedsTenure(registrationDate)) {
56	            points += 3;
57	        }
58	        return points;
59	    }
60	
61	    /**
62	     * @param points the membership points
63	     * @return the membership level from {@code 1} to {@code 4}
64	     */
65	    public static int of(int points) {
66	        if (points >= 6) {
67	            return 4;
68	        }
69	        if (points >= 4) {
70	            return 3;
71	        }
72	        if (points >= 2) {
73	            return 2;
74	        }
75	        return 1;
76	    }
77	
78	    private static boolean exceedsTenure(LocalDate registrationDate) {
79	        return registrationDate != null
80	            && FiscalYear.elapsed(registrationDate, LocalDate.now()) > TENURE_POINTS_YEARS;
81	    }
82	}
