2	
3	import java.util.Collection;
4	
5	/**
6	 * Soft-duplicate detection for new owners. A new owner that is not a hard (identity-key)
7	 * duplicate is nevertheless a <em>possible</em> duplicate when its identity key differs from an
8	 * existing owner's yet their {@link IdentityKey#soundex(String) soundex} last name and postcode match.
9	 */
10	public final class PossibleDuplicate {
11	
12	    private PossibleDuplicate() {
13	    }
14	
15	    /** Id of the first existing owner the given owner possibly duplicates, or {@code null} if none. */
16	    public static Integer of(Owner owner, Collection<Owner> existing) {
17	        return existing.stream()
18	            .filter(other -> matches(owner, other))
19	            .map(Owner::getId)
20	            .findFirst()
21	            .orElse(null);
22	    }
23	
24	    private static boolean matches(Owner owner, Owner other) {
25	        return owner.getPostcode() != null
26	            && owner.getPostcode().equalsIgnoreCase(other.getPostcode())
27	            && IdentityKey.soundex(owner.getLastName()).equals(IdentityKey.soundex(other.getLastName()))
28	            && !owner.getIdentityKey().equals(other.getIdentityKey());
29	    }
30	}
