20	
21	/**
22	 * Derives an owner's {@code ageBand} from a birth date, measured against the
23	 * owner's registration date: {@code MINOR} (under 18), {@code ADULT} (18-64) or
24	 * {@code SENIOR} (65+).
25	 */
26	public final class AgeBand {
27	
28	    private AgeBand() {
29	    }
30	
31	    /**
32	     * @param birthDate        the owner's date of birth, or {@code null}
33	     * @param registrationDate the date the age is measured against
34	     * @return the age band, or {@code null} when either date is absent
35	     */
36	    public static String of(LocalDate birthDate, LocalDate registrationDate) {
37	        if (birthDate == null || registrationDate == null) {
38	            return null;
39	        }
40	        int years = Period.between(birthDate, registrationDate).getYears();
41	        if (years < 18) {
42	            return "MINOR";
43	        }
44	        if (years < 65) {
45	            return "ADULT";
46	        }
47	        return "SENIOR";
48	    }
49	}
